	public boolean applyDye(int slot, ItemStack dyeStack, DyeColor dyeColor, boolean applyToAll) {
		if (slot < 0 || slot >= getStorageWrapper().getInventoryHandler().getSlots()) {
			return false;
		}

		StorageWrapper storageWrapper = getStorageWrapper();
		InventoryHandler invHandler = storageWrapper.getInventoryHandler();
		if (applyToAll) {
			boolean success = false;
			for (int i = 0; i < invHandler.getSlots(); i++) {
				success |= applyDye(i, dyeColor, invHandler);
			}
			if (!success) {
				return false;
			}
		} else {
			if (!applyDye(slot, dyeColor, invHandler)) {
				return false;
			}
		}
		setChanged();

		dyeStack.shrink(1);

		WorldHelper.notifyBlockUpdate(this);

		return true;
	}

	private boolean applyDye(int slot, DyeColor dyeColor, InventoryHandler invHandler) {
		ItemStack stackInSlot = invHandler.getStackInSlot(slot);
		if (stackInSlot.isEmpty() || dyeColor.equals(slotColors.get(slot))) {
			return false;
		}

		slotColors.put(slot, dyeColor);
		return true;
	}

	public int getSlotColor(int slot) {
		return slotColors.getOrDefault(slot, DyeColor.WHITE).getTextColor();
	}

	public boolean depositItem(Player player, InteractionHand hand, ItemStack stackInHand, int slot) {
		// noinspection ConstantConditions
		long gameTime = getLevel().getGameTime();
		boolean doubleClick = gameTime - lastDepositTime < 10;
		lastDepositTime = gameTime;

		StorageWrapper storageWrapper = getStorageWrapper();
		InventoryHandler invHandler = storageWrapper.getInventoryHandler();
		ItemStack stackInSlot = invHandler.getStackInSlot(slot);

		MemorySettingsCategory memorySettings = getStorageWrapper().getSettingsHandler().getTypeCategory(MemorySettingsCategory.class);

		if (doubleClick) {
			return depositFromAllOfPlayersInventory(player, slot, invHandler, stackInSlot, memorySettings);
		}

		if (stackInSlot.isEmpty()) {
			if (invHandler.isItemValid(slot, stackInHand, player)) {
				ItemStack result = invHandler.insertItemOnlyToSlot(slot, stackInHand, true);
				if (result.getCount() != stackInHand.getCount()) {
					result = invHandler.insertItemOnlyToSlot(slot, stackInHand, false);
					if (isLocked()) {
						memorySettings.selectSlot(slot);
						if (player instanceof ServerPlayer serverPlayer) {
							syncLinkedStorageContentsToPlayer(serverPlayer);
						}
					}
					player.setItemInHand(hand, result);
					return true;
				}
			}
		} else {
			ItemStack result = invHandler.insertItemOnlyToSlot(slot, stackInHand, true);
			if (result.getCount() != stackInHand.getCount()) {
				result = invHandler.insertItemOnlyToSlot(slot, stackInHand, false);
				if (isLocked()) {
					memorySettings.selectSlot(slot);
					if (player instanceof ServerPlayer serverPlayer) {
						syncLinkedStorageContentsToPlayer(serverPlayer);
					}
				}
				player.setItemInHand(hand, result);
				return true;
			}
		}

		return false;
	}

	private boolean depositFromAllOfPlayersInventory(Player player, int slot, InventoryHandler invHandler, ItemStack stackInSlot,
			MemorySettingsCategory memorySettings) {
		AtomicBoolean success = new AtomicBoolean(false);
		Predicate<ItemStack> memoryItemMatches = itemStack -> memorySettings.isSlotSelected(slot) && memorySettings.matchesFilter(slot, itemStack);
		CapabilityHelper.runOnItemHandler(player, playerInventory -> InventoryHelper.iterate(playerInventory, (playerSlot, playerStack) -> {
			if ((stackInSlot.isEmpty() && (memoryItemMatches.test(playerStack) || invHandler.isFilterItem(playerStack.getItem()))
					|| (!playerStack.isEmpty() && ItemStack.isSameItemSameComponents(stackInSlot, playerStack)))) {

				ItemStack result = invHandler.insertItemOnlyToSlot(slot, playerStack, true);
				if (result.getCount() < playerStack.getCount()) {
					ItemStack extracted = playerInventory.extractItem(playerSlot, playerStack.getCount() - result.getCount(), true);
					if (!extracted.isEmpty()) {
						invHandler.insertItemOnlyToSlot(slot, playerInventory.extractItem(playerSlot, extracted.getCount(), false), false);
						success.set(true);
					}
				}
			}
		}));
		return success.get();
	}

	boolean tryToTakeItem(Player player, int slot) {
		InventoryHandler inventoryHandler = getStorageWrapper().getInventoryHandler();
		ItemStack stackInSlot = inventoryHandler.getStackInSlot(slot);
		if (stackInSlot.isEmpty()) {
			return false;
		}

		int countToTake = player.isShiftKeyDown() ? Math.min(stackInSlot.getMaxStackSize(), stackInSlot.getCount()) : 1;
		ItemStack stackTaken = inventoryHandler.extractItem(slot, countToTake, false);

		if (player.getInventory().add(stackTaken)) {
			// noinspection ConstantConditions
			getLevel().playSound(null, getBlockPos(), SoundEvents.ITEM_PICKUP, SoundSource.PLAYERS, .2f,
					(RandHelper.getRandomMinusOneToOne(getLevel().random) * .7f + 1) * 2);
		} else {
			player.drop(stackTaken, false);
		}
		return true;
	}

	@Override
	void updateOpenBlockState(BlockState state, boolean open) {
		// noop
	}

	@Override
	public void onLoad() {
		super.onLoad();

		if (!isLinkedStorage()) {
			SettingsHandler settingsHandler = getStorageWrapper().getSettingsHandler();
			settingsHandler.getTypeCategory(MemorySettingsCategory.class).setIgnoreNbt(false);
			setFixedSettings(getStorageWrapper(), getStorageWrapper().getNumberOfInventorySlots());
			settingsHandler.getTypeCategory(ItemDisplaySettingsCategory.class).itemsChanged();
		}
	}

	@Override
	public void loadSynchronizedData(CompoundTag tag, HolderLookup.Provider registries) {
		super.loadSynchronizedData(tag, registries);
		showCounts = NBTHelper.getBoolean(tag, "showCounts").orElse(true);
		showFillLevels = NBTHelper.getBoolean(tag, "showFillLevels").orElse(false);
		slotColors = NBTHelper.getMap(tag, "slotColors", Integer::valueOf, (tagName, t) -> Optional.of(DyeColor.byId(((IntTag) t).getAsInt())))
				.orElseGet(HashMap::new);
	}

	@Override
	public void loadAdditional(CompoundTag tag, HolderLookup.Provider registries) {
		super.loadAdditional(tag, registries);
		if (level == null || !level.isClientSide()) {
			setFixedSettings(getStorageWrapper(), getStorageWrapper().getNumberOfInventorySlots());
		}
	}

	@Override
	protected void saveSynchronizedData(CompoundTag tag) {
		super.saveSynchronizedData(tag);
		if (!showCounts) {
			tag.putBoolean("showCounts", showCounts);
		}
		if (showFillLevels) {
			tag.putBoolean("showFillLevels", showFillLevels);
		}
		if (!slotColors.isEmpty()) {
			NBTHelper.putMap(tag, "slotColors", slotColors, String::valueOf, color -> IntTag.valueOf(color.getId()));
		}
	}

	@Override
	protected String getStorageType() {
		return STORAGE_TYPE;
	}

	@Override
	public float getSlotFillPercentage(int slot) {
		return slot < getSlotFillLevels().size() ? getSlotFillLevels().get(slot) : 0;
	}
}

	tag.putInt(NUMBER_OF_INVENTORY_SLOTS_TAG, getNumberOfInventorySlots());
	tag.putInt(NUMBER_OF_UPGRADE_SLOTS_TAG, getNumberOfUpgradeSlots());
	tag.putString(SORT_BY_TAG, sortBy.getSerializedName());
	return tag;
}

public void load(CompoundTag tag) {
	loadContents(tag);
	loadData(tag);

	if (inventoryHandler != null) {
		initInventoryHandler();
	}
	if (upgradeHandler != null) {
		getUpgradeHandler().refreshUpgradeWrappers();
	}
	if (Thread.currentThread().getThreadGroup() == SidedThreadGroups.SERVER && getRenderInfo().getUpgradeItems().size() != getUpgradeHandler().getSlots()) {
		getUpgradeHandler().setRenderUpgradeItems();
	}
}

void loadEndpointData(CompoundTag tag) {
	renderInfoNbt = tag.getCompound(RENDER_INFO_TAG);
	renderInfo.deserializeFrom(renderInfoNbt);
	renderInfoValidationPending = true;
	openTabId = NBTHelper.getInt(tag, OPEN_TAB_ID_TAG).orElse(-1);
	mainColor = NBTHelper.getInt(tag, MAIN_COLOR_TAG).orElse(-1);
	accentColor = NBTHelper.getInt(tag, ACCENT_COLOR_TAG).orElse(-1);
}

void loadCanonicalData(CompoundTag tag) {
	contentsNbt = tag.contains(CONTENTS_TAG) ? tag.getCompound(CONTENTS_TAG) : new CompoundTag();
	settingsNbt = tag.getCompound(SETTINGS_TAG);
	if (!tag.contains(SETTINGS_TAG)) {
		tag.put(SETTINGS_TAG, settingsNbt);
	}
	settingsHandler.reloadFrom(settingsNbt);
	numberOfInventorySlots = tag.getInt(NUMBER_OF_INVENTORY_SLOTS_TAG);
	numberOfUpgradeSlots = tag.getInt(NUMBER_OF_UPGRADE_SLOTS_TAG);
	sortBy = NBTHelper.getString(tag, SORT_BY_TAG).map(SortBy::fromName).orElse(SortBy.NAME);
	inventoryHandler = null;
	upgradeHandler = null;
	inventoryIOHandler = null;
}

private void loadData(CompoundTag tag) {
	settingsNbt = tag.getCompound(SETTINGS_TAG);
	settingsHandler.reloadFrom(settingsNbt);
	renderInfoNbt = tag.getCompound(RENDER_INFO_TAG);
	renderInfo.deserializeFrom(renderInfoNbt);
	renderInfoValidationPending = true;
	contentsUuid = NBTHelper.getTagValue(tag, UUID_TAG, CompoundTag::get).map(NbtUtils::loadUUID).orElse(null);
	openTabId = NBTHelper.getInt(tag, OPEN_TAB_ID_TAG).orElse(-1);
	sortBy = NBTHelper.getString(tag, SORT_BY_TAG).map(SortBy::fromName).orElse(SortBy.NAME);
	columnsTaken = NBTHelper.getInt(tag, "columnsTaken").orElse(0);
	loadSlotNumbers(tag);
	mainColor = NBTHelper.getInt(tag, MAIN_COLOR_TAG).orElse(-1);
	accentColor = NBTHelper.getInt(tag, ACCENT_COLOR_TAG).orElse(-1);
}

protected void loadSlotNumbers(CompoundTag tag) {
	numberOfInventorySlots = NBTHelper.getInt(tag, NUMBER_OF_INVENTORY_SLOTS_TAG).orElse(0);
	numberOfUpgradeSlots = NBTHelper.getInt(tag, NUMBER_OF_UPGRADE_SLOTS_TAG).orElse(-1);
	if (promoteSlotNumbersToDefaults()) {
		save();
	}
}

protected boolean promoteSlotNumbersToDefaults() {
	boolean changed = false;
	int defaultNumberOfInventorySlots = getDefaultNumberOfInventorySlots();
	if (numberOfInventorySlots < defaultNumberOfInventorySlots) {
		numberOfInventorySlots = defaultNumberOfInventorySlots;
		changed = true;
	}

	int defaultNumberOfUpgradeSlots = getDefaultNumberOfUpgradeSlots();
	if (numberOfUpgradeSlots < defaultNumberOfUpgradeSlots) {
		numberOfUpgradeSlots = defaultNumberOfUpgradeSlots;
		changed = true;
	}
	return changed;
}

private void loadContents(CompoundTag tag) {
	if (tag.contains(CONTENTS_TAG)) {
		contentsNbt = tag.getCompound(CONTENTS_TAG);
		onContentsNbtUpdated();
	}
}

